def most_frequent(nums):
    count = {}
    for num in nums:
        if num not in count:
            count[num] = 1
        else:
            count[num] += 1
    max_count = 0
    res = 0
    for key, val in count.items():
        if val > max_count:
            res = key
        max_count = max(max_count, val)
    return res

### Instruction:
Find the longest substring of a string without repeating characters

### Input:
string="abcabcbb"

### Response:
def longestSubstring(string): 
    start_index = max_length = 0
    visited = {} 

    # traverse through the string  
    for i in range(len(string)):  
        if string[i] in visited and start_index <= visited[string[i]]: 
            start_index = visited[string[i]] + 1
        else: 
            max_length = max(max_length, i - start_index + 1) 

        visited[string[i]] = i 

    return max_length

