### Instruction:
Create an algorithm to calculate the mean, mode and median in a given set of numbers.

### Response:
def mean(nums):
    return sum(nums)/len(nums)

def mode(nums):
    countDict = {}
    for num in nums:
        if num in countDict:
            countDict[num] += 1
        else:
            countDict[num] = 1
    maxValue = 0
    maxKey = -1
    for key, value in countDict.items():
        if value > maxValue:
            maxValue = value
            maxKey = key
    return maxKey

def median(nums):
    nums.sort()
    if len(nums) % 2 == 0:
        return (nums[len(nums)//2] + nums[len(nums)//2-1])/2
    else:
        return nums[(len(nums)-1)//2]

if __name__ == '__main__':
    nums = [1,2,2,2,3,4,5]
    print("Mean: ", mean(nums))
    print("Mode: ", mode(nums))
    print("Median: ", median(nums))

